parameters.jsCode:
// De AI-verrijking zit als tekst-string in het 'response'-veld.
// We parsen die naar echte velden, met een vangnet als het geen geldige JSON is.
const ruweTekst = $json.response;

let verrijking;
try {
  verrijking = JSON.parse(ruweTekst);
} catch (e) {
  // Model gaf geen geldige JSON terug: we geven een nette foutstatus door
  // in plaats van de flow te laten crashen.
  verrijking = {
    samenvatting: "Kon AI-output niet lezen als JSON.",
    jaren_ervaring: null,
    skills: [],
    seniority: "onbekend",
    fit_score: null,
    fit_toelichting: ruweTekst
  };
}

// We halen de originele kandidaatgegevens er weer bij via de Set-node,
// zodat naam/email/telefoon samen met de verrijking doorgaan.
const kandidaat = $('normaliseren').item.json;

return {
  naam: kandidaat.naam,
  email: kandidaat.email,
  telefoon: kandidaat.telefoon,
  functie: kandidaat.functie,
  samenvatting: verrijking.samenvatting,
  jaren_ervaring: verrijking.jaren_ervaring,
  skills: verrijking.skills,
  seniority: verrijking.seniority,
  fit_score: verrijking.fit_score,
  fit_toelichting: verrijking.fit_toelichting
};
